**BaseTest Class** is a parent class that contains common setup, teardown, and utility methods for all test classes.

**Purpose:**
- Centralize browser initialization
- Provide common functionality
- Reduce code duplication
- Enforce consistency

**Complete Implementation:**

```java
package com.automation.base;

import com.automation.utils.BrowserFactory;
import org.openqa.selenium.WebDriver;
import org.testng.annotations.*;
import java.time.Duration;

/**
 * Base class for all test classes
 * Provides common setup and teardown methods
 */
public class BaseTest {

    // ThreadLocal for parallel execution safety
    protected static ThreadLocal<WebDriver> driver = new ThreadLocal<>();

    /**
     * Get WebDriver instance for current thread
     */
    public static WebDriver getDriver() {
        return driver.get();
    }

    /**
     * Setup method - runs before each test method
     * Initializes browser and sets up configuration
     */
    @BeforeMethod(alwaysRun = true)
    @Parameters({"browser"})  // Parameter from testng.xml
    public void setUp(@Optional("chrome") String browser) {
        System.out.println("\n========== Test Setup ==========");
        System.out.println("Browser: " + browser);

        // Create browser instance
        WebDriver webDriver = BrowserFactory.createDriver(browser);
        driver.set(webDriver);

        // Configure browser
        getDriver().manage().window().maximize();
        getDriver().manage().deleteAllCookies();

        // Set timeouts
        getDriver().manage().timeouts()
            .implicitlyWait(Duration.ofSeconds(10));
        getDriver().manage().timeouts()
            .pageLoadTimeout(Duration.ofSeconds(30));

        System.out.println("Browser initialized successfully");
    }

    /**
     * Teardown method - runs after each test method
     * Closes browser and cleans up resources
     */
    @AfterMethod(alwaysRun = true)
    public void tearDown() {
        System.out.println("\n========== Test Teardown ==========");

        if (getDriver() != null) {
            getDriver().quit();
            driver.remove();
            System.out.println("Browser closed successfully");
        }
    }

    // ========== Common Navigation Methods ==========

    /**
     * Navigate to specified URL
     */
    protected void navigateTo(String url) {
        System.out.println("Navigating to: " + url);
        getDriver().get(url);
    }

    /**
     * Get current page title
     */
    protected String getPageTitle() {
        return getDriver().getTitle();
    }

    /**
     * Get current page URL
     */
    protected String getCurrentUrl() {
        return getDriver().getCurrentUrl();
    }

    /**
     * Refresh current page
     */
    protected void refreshPage() {
        System.out.println("Refreshing page");
        getDriver().navigate().refresh();
    }

    // ========== Common Wait Methods ==========

    /**
     * Wait for specified milliseconds
     */
    protected void waitFor(long milliseconds) {
        try {
            Thread.sleep(milliseconds);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

    // ========== Common Verification Methods ==========

    /**
     * Verify page title
     */
    protected boolean verifyPageTitle(String expectedTitle) {
        String actualTitle = getPageTitle();
        return actualTitle.equals(expectedTitle);
    }

    /**
     * Verify URL contains text
     */
    protected boolean verifyUrlContains(String urlPart) {
        String currentUrl = getCurrentUrl();
        return currentUrl.contains(urlPart);
    }
}
```

**Usage in Test Classes:**

