**BrowserFactory** is a creational design pattern that provides a centralized place to create WebDriver instances for different browsers.

**Benefits:**
- Single place to manage browser creation
- Easy to add new browsers
- Consistent browser configuration
- Support for headless mode
- Cross-browser testing made simple

**Complete Implementation:**

```java
package com.automation.utils;

import io.github.bonigarcia.wdm.WebDriverManager;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;
import org.openqa.selenium.edge.EdgeDriver;
import org.openqa.selenium.edge.EdgeOptions;
import org.openqa.selenium.firefox.FirefoxDriver;
import org.openqa.selenium.firefox.FirefoxOptions;
import org.openqa.selenium.safari.SafariDriver;

/**
 * Factory class for creating WebDriver instances
 * Supports multiple browsers with different configurations
 */
public class BrowserFactory {

    /**
     * Create WebDriver based on browser name
     * 
     * @param browserName Name of browser (chrome, firefox, edge, safari)
     * @return WebDriver instance
     */
    public static WebDriver createDriver(String browserName) {
        WebDriver driver = null;

        switch (browserName.toLowerCase().trim()) {
            case "chrome":
                driver = createChromeDriver();
                break;

            case "firefox":
                driver = createFirefoxDriver();
                break;

            case "edge":
                driver = createEdgeDriver();
                break;

            case "safari":
                driver = createSafariDriver();
                break;

            case "chrome-headless":
                driver = createChromeDriverHeadless();
                break;

            case "firefox-headless":
                driver = createFirefoxDriverHeadless();
                break;

            default:
                System.out.println("Browser '" + browserName + 
                    "' not supported. Launching Chrome.");
                driver = createChromeDriver();
        }

        return driver;
    }

    /**
     * Create Chrome WebDriver with options
     */
    private static WebDriver createChromeDriver() {
        WebDriverManager.chromedriver().setup();

        ChromeOptions options = new ChromeOptions();
        options.addArguments("--start-maximized");
        options.addArguments("--disable-notifications");
        options.addArguments("--disable-popup-blocking");
        options.addArguments("--disable-infobars");
        options.addArguments("--remote-allow-origins=*");

        System.out.println("Creating Chrome driver");
        return new ChromeDriver(options);
    }

    /**
     * Create Chrome WebDriver in headless mode
     */
    private static WebDriver createChromeDriverHeadless() {
        WebDriverManager.chromedriver().setup();

        ChromeOptions options = new ChromeOptions();
        options.addArguments("--headless=new");
        options.addArguments("--disable-gpu");
        options.addArguments("--window-size=1920,1080");
        options.addArguments("--no-sandbox");
        options.addArguments("--disable-dev-shm-usage");

        System.out.println("Creating Chrome headless driver");
        return new ChromeDriver(options);
    }

    /**
     * Create Firefox WebDriver with options
     */
    private static WebDriver createFirefoxDriver() {
        WebDriverManager.firefoxdriver().setup();

        FirefoxOptions options = new FirefoxOptions();
        options.addArguments("--width=1920");
        options.addArguments("--height=1080");

        System.out.println("Creating Firefox driver");
        return new FirefoxDriver(options);
    }

    /**
     * Create Firefox WebDriver in headless mode
     */
    private static WebDriver createFirefoxDriverHeadless() {
        WebDriverManager.firefoxdriver().setup();

        FirefoxOptions options = new FirefoxOptions();
        options.addArguments("--headless");
        options.addArguments("--width=1920");
        options.addArguments("--height=1080");

        System.out.println("Creating Firefox headless driver");
        return new FirefoxDriver(options);
    }

    /**
     * Create Edge WebDriver with options
     */
    private static WebDriver createEdgeDriver() {
        WebDriverManager.edgedriver().setup();

        EdgeOptions options = new EdgeOptions();
        options.addArguments("--start-maximized");
        options.addArguments("--disable-notifications");

        System.out.println("Creating Edge driver");
        return new EdgeDriver(options);
    }

    /**
     * Create Safari WebDriver
     * Note: Safari doesn't support many options
     */
    private static WebDriver createSafariDriver() {
        System.out.println("Creating Safari driver");
        return new SafariDriver();
    }

    /**
     * Create driver with custom Chrome options
     */
    public static WebDriver createDriverWithOptions(ChromeOptions options) {
        WebDriverManager.chromedriver().setup();
        System.out.println("Creating Chrome driver with custom options");
        return new ChromeDriver(options);
    }
}
```

