package com.automation.tests;

import com.automation.base.BaseTest;
import com.automation.config.ConfigReader;
import org.openqa.selenium.By;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.support.ui.ExpectedConditions;
import org.openqa.selenium.support.ui.WebDriverWait;
import org.testng.Assert;
import org.testng.annotations.Test;
import java.time.Duration;

public class LoginTests extends BaseTest {

    @Test(priority = 1, groups = {"smoke"})
    public void testValidLogin() {
        System.out.println("Test: Valid Login");

        navigateTo(ConfigReader.get("baseUrl"));

        WebDriverWait wait = new WebDriverWait(
            getDriver(), 
            Duration.ofSeconds(ConfigReader.getInt("explicitWait"))
        );

        WebElement username = wait.until(
            ExpectedConditions.visibilityOfElementLocated(By.id("username"))
        );
        username.sendKeys(ConfigReader.get("validUsername"));

        WebElement password = getDriver().findElement(By.id("password"));
        password.sendKeys(ConfigReader.get("validPassword"));

        WebElement submitBtn = getDriver().findElement(By.id("submit"));
        submitBtn.click();

        String currentUrl = getDriver().getCurrentUrl();
        Assert.assertTrue(
            currentUrl.contains("logged-in-successfully"),
            "Login failed"
        );

        System.out.println("✓ Valid login test passed");
    }

    @Test(priority = 2, groups = {"regression"})
    public void testInvalidLogin() {
        System.out.println("Test: Invalid Login");

        navigateTo(ConfigReader.get("baseUrl"));

        getDriver().findElement(By.id("username")).sendKeys("invalid");
        getDriver().findElement(By.id("password")).sendKeys("wrong");
        getDriver().findElement(By.id("submit")).click();

        WebDriverWait wait = new WebDriverWait(
            getDriver(),
            Duration.ofSeconds(10)
        );

        WebElement error = wait.until(
            ExpectedConditions.visibilityOfElementLocated(By.id("error"))
        );

        Assert.assertTrue(error.isDisplayed(), "Error message not shown");
        System.out.println("✓ Invalid login test passed");
    }
}
